  [811323] = {
    [1] = {
      beijing = 4304,
      dialog = 3,
      music = "52_Daily03",
      renwu = "npc",
      sentence = "眼前店里的手工艺品琳琅满目，我瞧瞧这个，又看看那个。",
      next = {2}
    },
    [2] = {
      beijing = 4304,
      dialog = 3,
      music = "52_Daily03",
      renwu = "npc",
      role1 = 260000,
      role2 = 201106,
      role3 = 201201,
      role5 = 260404,
      ruchang = -1,
      sentence = "许墨被目不暇接的我抛弃在身后不远处，目光掠过我依次停留的地方，眨了眨眼。",
      next = {3}
    },
    [3] = {
      beijing = 4304,
      dialog = 2,
      idx = 2,
      music = "52_Daily03",
      renming = "许墨",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "$u。",
      next = {4}
    },
    [4] = {
      beijing = 4304,
      dhead = 111,
      dialog = 1,
      music = "52_Daily03",
      renming = "$u",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "嗯？怎么啦？",
      next = {5}
    },
    [5] = {
      beijing = 4304,
      dialog = 3,
      music = "52_Daily03",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "被许墨叫了声，我放下手里的扇坠，朝他投去一个疑惑的目光。",
      next = {6}
    },
    [6] = {
      beijing = 4304,
      dialog = 3,
      music = "52_Daily03",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "许墨走过来，牵住了我的手。",
      next = {7}
    },
    [7] = {
      beijing = 4304,
      dialog = 2,
      idx = 2,
      music = "52_Daily03",
      renming = "许墨",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "没什么，只是你走得有些太快。",
      next = {8}
    },
    [8] = {
      beijing = 4304,
      dialog = 3,
      music = "52_Daily03",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "我一愣，触及到他温暖的掌心，忍不住笑了。",
      next = {9}
    },
    [9] = {
      beijing = 4304,
      dhead = 107,
      dialog = 1,
      music = "52_Daily03",
      renming = "$u",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "许墨，我们来给对方互相挑一件礼物吧。",
      next = {10}
    },
    [10] = {
      beijing = 4304,
      dialog = 3,
      music = "52_Daily03",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "目光扫到店里的纪念品，我晃了晃许墨的手，朝他眨眨眼。",
      next = {11}
    },
    [11] = {
      beijing = 4304,
      dhead = 107,
      dialog = 1,
      music = "52_Daily03",
      renming = "$u",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "虽然我自己也不是很了解相关的知识……",
      next = {12}
    },
    [12] = {
      beijing = 4304,
      dhead = 101,
      dialog = 1,
      music = "52_Daily03",
      renming = "$u",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "但仅仅从外行的角度来看，感觉它们的做工都很精湛。",
      next = {13}
