      beijing = 4304,
      dhead = 101,
      dialog = 1,
      music = "52_Daily03",
      renming = "$u",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "用来给许教授当礼物，再合适不过啦~",
      next = {14}
    },
    [14] = {
      beijing = 4304,
      dialog = 3,
      music = "52_Daily03",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "许墨被我晃着手，忍不住眼中划过一丝笑意，慢悠悠开口。",
      next = {15}
    },
    [15] = {
      beijing = 4304,
      dialog = 2,
      idx = 2,
      music = "52_Daily03",
      renming = "许墨",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "这些仿制品经营出售，背后必然需要相应的技术人员来制作。",
      next = {16}
    },
    [16] = {
      beijing = 4304,
      dialog = 2,
      idx = 2,
      music = "52_Daily03",
      renming = "许墨",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "而他们都是传承了和保留了传统的制作工艺。",
      next = {17}
    },
    [17] = {
      beijing = 4304,
      dialog = 2,
      idx = 2,
      music = "52_Daily03",
      renming = "许墨",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "所以即使是一个仿制品，从艺术构思到操作的手法技巧，也都是得到了前人口传心授的传承。",
      next = {18}
    },
    [18] = {
      beijing = 4304,
      dialog = 3,
      music = "52_Daily03",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      sentence = "他科普完，侧眸瞧了我一眼，语气含着笑意。",
      next = {19}
    },
    [19] = {
      beijing = 4304,
      dialog = 2,
      idx = 2,
      music = "52_Daily03",
      renming = "许墨",
      renwu = "npc",
      role1 = 260000,
      role2 = 201105,
      role3 = 201201,
      role5 = 260404,
      ruchang = 9,
      sentence = "所以我认为，这样用心的礼物，也同样配得上你。",
      next = {20}
    },
    [20] = {
      beijing = 4304,
      dialog = 3,
      music = "52_Daily03",
      renwu = "npc",
      sentence = "听完许墨的话，我的心忍不住轻轻一动，认真地挑起礼物来。",
